// Reversible, tap-only room decorating. Saved rooms are independent of machine parts.
export const roomThemes={sky:{name:'Sky blue',wall:'#b6d5e2',floor:'#e6d9bd'},forest:{name:'Forest green',wall:'#bfd5ba',floor:'#d2c19f'},sunset:{name:'Warm sunset',wall:'#e6c5b1',floor:'#d8bb9d'},space:{name:'Space purple',wall:'#c5bddc',floor:'#b2b3c8'},contrast:{name:'High contrast',wall:'#ffffff',floor:'#e2e2e2'}};
export const roomFurniture={bed:{name:'Bed',icon:'🛏️'},plant:{name:'Plant pot',icon:'🌱'},desk:{name:'Science desk',icon:'🔬'},dock:{name:'PIP charging dock',icon:'🤖'},shelf:{name:'Discovery shelf',icon:'🗄️'},cushion:{name:'Cozy cushion',icon:'🟨'}};
export const roomSpots=Array.from({length:6},(_,i)=>({x:[220,500,780][i%3],y:i<3?255:410,name:['Left wall','Middle wall','Right wall','Left floor','Middle floor','Right floor'][i]}));
const roomToken=t=>typeof t==='string'&&(Object.hasOwn(roomFurniture,t)||/^(sample|memory|plant):[a-z0-9-]{1,60}$/.test(t));
const roomSnapshot=r=>({theme:r.theme,slots:[...r.slots]});
export function normalizeRooms(raw={}){const rooms={};for(const [id,q]of Object.entries(raw&&typeof raw==='object'?raw:{}).slice(-80)){if(!/^t[1-9]\d{0,5}$/.test(id)||!q||typeof q!=='object')continue;rooms[id]={theme:Object.hasOwn(roomThemes,q.theme)?q.theme:'sky',slots:Array.from({length:6},(_,i)=>roomToken(q.slots?.[i])?q.slots[i]:null),history:(Array.isArray(q.history)?q.history:[]).slice(-12).filter(v=>v&&Object.hasOwn(roomThemes,v.theme)&&Array.isArray(v.slots)).map(v=>({theme:v.theme,slots:Array.from({length:6},(_,i)=>roomToken(v.slots[i])?v.slots[i]:null)}))};}return rooms;}
export function ensureRoom(s,id){s.rooms??={};if(!s.rooms[id]){const p=s.placements.find(p=>p.id===id);if(!p||p.snapshot.type!=='habitat'||Object.keys(s.rooms).length>=80)return false;s.rooms[id]={theme:'sky',slots:['bed',null,'dock',null,null,null],history:[]};}s.roomOpen=id;s.roomChoice=null;s.roomMoving=null;return true;}
function rememberRoom(r){r.history.push(roomSnapshot(r));r.history=r.history.slice(-12);}
export function roomName(token,ctx={}){if(!token)return 'Empty spot';if(roomFurniture[token])return roomFurniture[token].name;const [kind,id]=token.split(':');return (ctx[kind==='sample'?'minerals':kind==='plant'?'plants':'discoveries']||[]).find(o=>o.id===id)?.name||{sample:'My sample',plant:'My plant',memory:'My discovery'}[kind]||'My decoration';}
export function roomAction(s,a,ctx={}){const r=s.rooms?.[s.roomOpen];let route=null,message='',effect=null,pause=null;if(a.type==='exit'){s.roomOpen=null;s.roomChoice=null;s.roomMoving=null;return {route,message:'Back outside. Your room is saved.',effect,pause:false};}if(!r)return {route:'library:0',message:'Choose a habitat room.',effect,pause};
 if(a.type==='choose'&&roomToken(a.item)){const [kind,id]=a.item.split(':');const list=kind==='sample'?ctx.minerals:kind==='plant'?ctx.plants:kind==='memory'?ctx.discoveries:null;if(list&&!list.some(o=>o.id===id))return {route:'displays',message:'Collect this discovery first.',effect,pause};s.roomChoice=a.item;s.roomMoving=null;message='Tap any large room spot to place '+roomName(a.item,ctx)+'.';}
 if(a.type==='spot'&&Number.isInteger(a.slot)&&a.slot>=0&&a.slot<6){if(s.roomChoice){rememberRoom(r);if(Number.isInteger(s.roomMoving))r.slots[s.roomMoving]=null;r.slots[a.slot]=s.roomChoice;s.roomChoice=null;s.roomMoving=null;message='Placed. Your room is saved.';}else route='spot:'+a.slot;}
 if(a.type==='move'&&r.slots[a.slot]){s.roomChoice=r.slots[a.slot];s.roomMoving=a.slot;message='Tap a new spot. Your item stays put until you choose.';}
 if(a.type==='remove'&&Number.isInteger(a.slot)&&a.slot>=0&&a.slot<6){rememberRoom(r);r.slots[a.slot]=null;message='Put away. You can choose it again anytime.';}
 if(a.type==='theme'&&Object.hasOwn(roomThemes,a.value)){rememberRoom(r);r.theme=a.value;message='Room color saved.';}
 if(a.type==='undo'&&s.roomChoice){s.roomChoice=null;s.roomMoving=null;return {route:null,message:'Placement canceled. Your room stays as it was.',effect:null,pause:null};}if(a.type==='undo'){const old=r.history.pop();if(old){r.theme=old.theme;r.slots=[...old.slots];}s.roomChoice=null;s.roomMoving=null;message='Last room change undone.';}
 if(a.type==='cancel'){s.roomChoice=null;s.roomMoving=null;message='Placement canceled. Your room stays as it was.';}
 if(a.type==='resume'){pause=false;message='Ready to explore your room.';}
 if(a.type==='use'){const item=r.slots[a.slot];if(item==='bed'){pause=true;message='Resting. Tap Resume or Exit whenever you like.';}else if(item==='desk')effect='journal';else{route='look:'+a.slot;message=item==='dock'?'PIP is ready. There is no battery timer to manage.':'Look closely. Every discovery has a story.';}}
 return {route,message,effect,pause};}
const roomPage=(label,route)=>({label,type:'page',route});
export function roomView(s,route='furniture:0',ctx={}){const [kind,arg='0']=route.split(':'),r=s.rooms?.[s.roomOpen],n=Math.max(0,parseInt(arg)||0),back=roomPage('← My room','close'),v=(title,text,actions)=>({title,text,actions});
 if(kind==='library'){const ids=Object.keys(s.rooms||{}),list=ids.slice(n*3,n*3+3);return v('My saved habitat rooms',ids.length?'Rooms stay saved when habitats move or are packed.':'Enter a placed habitat to make a room.',[...list.map(id=>({label:'🏠 Room '+id.slice(1)+(s.placements.some(p=>p.id===id)?'':' / packed'),type:'open',id})),n?roomPage('← Previous rooms','library:'+(n-1)):{label:'← My Machines',type:'machines'},...(ids.length>(n+1)*3?[roomPage('More rooms →','library:'+(n+1))]:[])]);}
 if(!r)return roomView(s,'library:0',ctx);
 if(kind==='furniture'){const items=Object.entries(roomFurniture).slice(n*3,n*3+3);return v('Decorate my room','Tap an item, then tap a large spot. Replacing and moving are free. No dragging is needed.',[...items.map(([item,f])=>({label:f.icon+' '+f.name,type:'choose',item})),n?roomPage('← Previous furniture','furniture:0'):back,...(n===0?[roomPage('More furniture →','furniture:1')]:[])]);}
 if(kind==='colors')return v('My room colors','Choose a color. Shapes and labels stay the same.',Object.entries(roomThemes).map(([value,t])=>({label:t.name,type:'theme',value})).concat([back]));
 if(kind==='displays')return v('My discoveries at home','Display only things you have encountered. Samples, plants and memories can be moved freely.',[roomPage('💎 My minerals and fossils','samples:0'),roomPage('🌱 My collected plants','plants:0'),roomPage('📒 My adventure memories','memories:0'),back]);
 if(['samples','plants','memories'].includes(kind)){const field=kind==='samples'?'minerals':kind==='plants'?'plants':'discoveries',prefix=kind==='samples'?'sample':kind==='plants'?'plant':'memory',list=ctx[field]||[];return v('My '+kind,list.length?'Choose a keepsake, then tap a room spot.':'This shelf is ready. Explore to collect something to display.',[...list.slice(n*3,n*3+3).map(o=>({label:(o.icon||'🔎')+' '+o.name,type:'choose',item:prefix+':'+o.id})),n?roomPage('← Previous',''+kind+':'+(n-1)):roomPage('← My displays','displays'),...(list.length>(n+1)*3?[roomPage('More discoveries →',kind+':'+(n+1))]:[])]);}
 if(kind==='spot'){const item=r.slots[n];return v(roomName(item,ctx),item?'Move, put away or try this item. Nothing is lost.':'This spot is empty. Choose something to place here.',item?[{label:item==='bed'?'☾ Rest here':item==='desk'?'📒 Open my journal':item==='dock'?'🤖 Visit PIP’s dock':'🔎 Look closer',type:'use',slot:n},{label:'↔ Move this item',type:'move',slot:n},{label:'📦 Put away',type:'remove',slot:n},back]:[roomPage('＋ Choose furniture','furniture:0'),roomPage('💎 My displays','displays'),back]);}
 if(kind==='look'){const item=r.slots[n];return v(roomName(item,ctx),item==='plant'||item?.startsWith('plant:')?'Plants need suitable light, water, air and nutrients. This room decoration never needs timed care.':item==='dock'?'PIP’s dock is a cozy place to get ready. PIP stays available and never runs out of help.':'A keepsake from my adventures. My real discoveries stay recorded in the journal.',[{label:'📒 My journal',type:'journal'},back]);}
 if(kind==='help')return v('PIP / Make yourself at home','Tap furniture, then tap a spot. Tap an item to move or put it away. Undo reverses a change. The door always leads outside.',[roomPage('🛏️ Choose furniture','furniture:0'),roomPage('💎 Show my discoveries','displays'),{label:'↶ Undo a room change',type:'undo'},{label:'▶ Resume',type:'resume'},back]);
 return v('My room','Your layout is saved.',[back]);
}
export const roomArtKeys=[...Object.keys(roomFurniture),'sample','memory','plant-display'];
export function roomItemArt(token){const kind=token?.split(':')[0],type=kind==='sample'?'sample':kind==='memory'?'memory':kind==='plant'&&token.includes(':')?'plant-display':token;let a='';const line='stroke="#17384a" stroke-width="4"';
 if(type==='bed')a=`<rect x="20" y="40" width="200" height="65" rx="10" fill="#91adc6" ${line}/><rect x="25" y="20" width="50" height="80" rx="12" fill="#fffbed" ${line}/><path d="M82 40h128v55H82z" fill="#b7d0b5"/><path d="M30 104v24m180-24v24" ${line}/>`;
 else if(type==='plant'||type==='plant-display')a=`<path d="M87 90h70l-10 42H97z" fill="#bd8f71" ${line}/><path d="M122 94V35" stroke="#4b7d59" stroke-width="7"/><path d="M122 70Q55 65 72 25q48 0 50 45m0-20q0-50 53-35 0 40-53 35" fill="#6c9f75" ${line}/>`;
 else if(type==='desk')a=`<path d="M20 76h200v14H20zM35 90v42m170-42v42" fill="#bcaa87" ${line}/><path d="M110 67q40-5 20-38m-15 0h35m-35 0V12h20v17M90 68h70" fill="none" ${line}/><rect x="35" y="45" width="55" height="26" fill="#d8e1cc" ${line}/>`;
 else if(type==='dock')a=`<path d="M50 110l25-28h95l24 28-16 18H65z" fill="#a7bac2" ${line}/><rect x="80" y="21" width="80" height="65" rx="17" fill="#dbe4d9" ${line}/><rect x="90" y="36" width="60" height="25" rx="8" fill="#28495e"/><path d="M103 48h9m16 0h9M85 111h70" stroke="#35d3c9" stroke-width="6"/>`;
 else if(type==='shelf')a=`<path d="M25 20h190v108H25zM25 72h190" fill="#ae9576" ${line}/><path d="M55 35h35v25H55zM120 85h45v28h-45z" fill="#c9c0df" ${line}/>`;
 else if(type==='cushion')a=`<path d="M45 55q70-55 150 0l-12 65H58z" fill="#d5b37f" ${line}/><path d="M65 65q55-25 110 0" fill="none" ${line}/>`;
 else if(type==='sample')a=`<path d="M40 110h160v18H40z" fill="#a7bac2" ${line}/><path d="M76 104L65 53l35-35 35 15 29 64-34 16z" fill="#b8a8d1" ${line}/><path d="M100 18v82m35-67-35 67-35-47" fill="none" ${line}/>`;
 else a=`<rect x="45" y="17" width="150" height="112" rx="8" fill="#fffbed" ${line}/><path d="M60 110l45-45 28 25 29-45 20 65z" fill="#9bbfa8"/><circle cx="90" cy="44" r="13" fill="#d9c586"/>`;
 return `<svg xmlns="http://www.w3.org/2000/svg" width="240" height="140" viewBox="0 0 240 140">${a}</svg>`;
}
export function roomBackdrop(theme='sky'){const t=roomThemes[theme]||roomThemes.sky;return `<svg xmlns="http://www.w3.org/2000/svg" width="1000" height="600"><rect width="1000" height="600" fill="#12394c"/><rect x="10" y="95" width="980" height="425" rx="15" fill="${t.wall}"/><path d="M10 330h980v190H10z" fill="${t.floor}"/><path d="M10 330h980M10 425h980M130 330v190m260-190v190m220-190v190m260-190v190" stroke="#17384a" stroke-opacity=".2" stroke-width="2"/><rect x="892" y="155" width="72" height="115" rx="9" fill="#17384a"/><path d="M908 176h39v65h-39z" fill="#8fb9bf"/><path d="M932 210h10" stroke="#35d3c9" stroke-width="5"/></svg>`;}
